    "/api/salon/members/{target_user_id}/deactivate": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Временно деактивировать сотрудника салона
         * @description Делает мастера или администратора `TEMPORARILY_UNAVAILABLE` только в период
         *     `[from, to)`: `from` включительно, `to` исключительно. До будущего `from`
         *     сотрудник остаётся `ACTIVE`; после `to` автоматически возвращается в `ACTIVE`.
         *     Время передаётся с часовым смещением (например, `+03:00`) или в UTC;
         *     сервер сравнивает абсолютные моменты времени. Для периода 19–25 мая
         *     передайте `from: 2026-05-19T00:00:00+03:00` и
         *     `to: 2026-05-26T00:00:00+03:00`.
         *     Владелец может деактивировать мастера и администратора,
         *     администратор — только мастера. На период деактивации свободные слоты сотрудника
         *     не выдаются и бронирование невозможно.
         *     Для причины «Другое» клиент передаёт собственный непустой текст до 100 символов.
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path: {
                    target_user_id: number;
                };
                cookie?: never;
            };
            requestBody: {
                content: {
                    "application/json": {
                        /** @description Произвольный текст причины; для «Другое» передаётся текст пользователя. */
                        reason: string;
                        /**
                         * Format: date-time
                         * @example 2026-05-19T00:00:00+03:00
                         */
                        from: string;
                        /**
                         * Format: date-time
                         * @description Исключительная граница; должно быть позже `from` и находиться в будущем.
                         * @example 2026-05-26T00:00:00+03:00
                         */
                        to: string;
                    };
                };
            };
            responses: {
                /** @description Сотрудник деактивирован */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        /**
                         * @example {
                         *       "success": true,
                         *       "message": "Member deactivated successfully",
                         *       "codeError": null,
                         *       "error_code": null,
                         *       "data": {
                         *         "member_id": 7,
                         *         "user_id": 21,
                         *         "member_type": "MASTER",
                         *         "member_status": "ACTIVE",
                         *         "reason": "Отпуск",
                         *         "from": "2026-05-19T00:00:00+03:00",
                         *         "to": "2026-05-26T00:00:00+03:00"
                         *       }
                         *     }
                         */
                        "application/json": components["schemas"]["SalonMemberDeactivationResponse"];
                    };
                };
                /** @description Некорректное тело запроса */
                400: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["ErrorResponse"];
                    };
                };
                401: components["responses"]["Unauthorized"];
                403: components["responses"]["Forbidden"];
                /** @description Сотрудник уже деактивирован или ожидает начала ранее заданного периода. */
                409: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        /**
                         * @example {
                         *       "success": false,
                         *       "message": "User is already deactivated",
                         *       "codeError": "conflict",
                         *       "error_code": "conflict",
                         *       "data": null
                         *     }
                         */
                        "application/json": components["schemas"]["ErrorResponse"];
                    };
                };
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
